using System.Collections.Generic;

namespace ConsoleOverlay
{
    // Generado: traducciones incluidas. El texto en español es la clave.
    internal static class Lang
    {
        public static Dictionary<string, string> For(string code)
        {
            switch (code)
            {
                case "en": return BuildEN();
                case "fr": return BuildFR();
                case "de": return BuildDE();
                case "pt": return BuildPT();
                case "it": return BuildIT();
                case "ru": return BuildRU();
                case "zh": return BuildZH();
                case "ja": return BuildJA();
                case "pl": return BuildPL();
                case "tr": return BuildTR();
                case "ko": return BuildKO();
                case "nl": return BuildNL();
                case "uk": return BuildUK();
                case "zht": return BuildZHT();
                default: return null;
            }
        }

