            d["Mayús"] = "Umschalt";
            d["La pulsación larga debe estar entre 300 y 3000 ms."] = "Der lange Tastendruck muss zwischen 300 und 3000 ms liegen.";
            d["La tecla del menú y la de finalizar juego no pueden ser la misma."] = "Menütaste und Taste zum Beenden des Spiels dürfen nicht identisch sein.";
            d["El atajo de captura no es válido. Ejemplo: Ctrl+Shift+S."] = "Das Screenshot-Kürzel ist ungültig. Beispiel: Strg+Shift+S.";
            d["El atajo de guardar clip no es válido. Ejemplo: Ctrl+Shift+E."] = "Das Kürzel zum Speichern eines Clips ist ungültig. Beispiel: Strg+Shift+E.";
            d["El atajo de ver capturas no es válido. Ejemplo: Ctrl+Shift+G."] = "Das Kürzel zum Anzeigen der Aufnahmen ist ungültig. Beispiel: Strg+Shift+G.";
            d["Los comandos de reiniciar y apagar no pueden estar vacíos."] = "Die Befehle für Neustart und Herunterfahren dürfen nicht leer sein.";
            d["etiqueta «No pausar»"] = "Tag „Nicht pausieren“";
            d["anticheat activo"] = "Anticheat aktiv";
            d["juego como administrador"] = "Spiel läuft als Administrator";
            d["Idioma del menú:"] = "Menüsprache:";
            d["Se aplica al guardar. Para corregir o añadir un idioma, crea un archivo lang\\xx.txt en la carpeta de datos del plugin (una línea por frase: original, tabulador, traducción)."] = "Wird beim Speichern übernommen. Um eine Sprache zu korrigieren oder hinzuzufügen, lege im Datenordner des Plugins eine Datei lang\\xx.txt an (eine Zeile pro Satz: Original, Tabulator, Übersetzung).";
            d["Modificadores de los dos atajos. Asigna después estas combinaciones a un botón del mando con JoyToKey."] = "Modifikatoren der beiden Kürzel. Weise diese Kombinationen anschließend mit JoyToKey einer Controller-Taste zu.";
            d["Tecla del menú:"] = "Menütaste:";
            d["Pulsación corta: abrir el menú del juego, o volver al juego. Pulsación larga: menú de energía."] = "Kurz drücken: Spielmenü öffnen oder zum Spiel zurückkehren. Lang drücken: Energiemenü.";
            d["Tecla de finalizar juego:"] = "Taste zum Beenden des Spiels:";
            d["Cierra el juego directamente, sin confirmación."] = "Beendet das Spiel direkt, ohne Nachfrage.";
            d["Duración de la pulsación larga (ms):"] = "Dauer des langen Tastendrucks (ms):";
            d["Usar el botón PS / Guide del mando para abrir el menú"] = "PS-/Guide-Taste des Controllers zum Öffnen des Menüs verwenden";
            d["Pulsación corta: abrir el menú o volver al juego. Pulsación larga: menú de energía. Si otro programa ya usa ese botón (por ejemplo Steam o GameHQ), desactiva allí su acción para que no se solapen."] = "Kurz drücken: Menü öffnen oder zum Spiel zurückkehren. Lang drücken: Energiemenü. Wenn ein anderes Programm diese Taste schon belegt (z. B. Steam oder GameHQ), deaktiviere dort die Aktion, damit sie sich nicht überschneiden.";
            d["Iconos de los botones:"] = "Tastensymbole:";
            d["El menú puede accionar tu programa de capturas (GameHQ, NVIDIA App, Steam, Xbox Game Bar...) enviándole su atajo de teclado. Elige uno para rellenar los atajos habituales y corrígelos si los has cambiado en ese programa. Los que dejes vacíos no aparecen en el menú. Formato: Ctrl+Shift+S, Alt+F1, Win+Alt+PrtScn..."] = "Das Menü kann dein Aufnahmeprogramm (GameHQ, NVIDIA App, Steam, Xbox Game Bar ...) steuern, indem es dessen Tastenkürzel sendet. Wähle eines aus, um die üblichen Kürzel einzutragen, und korrigiere sie, falls du sie dort geändert hast. Leere Felder erscheinen nicht im Menü. Format: Strg+Shift+S, Alt+F1, Win+Alt+PrtScn ...";
            d["Programa:"] = "Programm:";
            d["Capturar pantalla:"] = "Screenshot aufnehmen:";
            d["Guardar clip:"] = "Clip speichern:";
            d["Ver capturas:"] = "Aufnahmen ansehen:";
            d["Carpetas extra con capturas y clips (opcional, separadas por punto y coma):"] = "Zusätzliche Ordner mit Screenshots und Clips (optional, durch Semikolon getrennt):";
            d["El menú ya busca solo en las carpetas habituales (Vídeos\\GameHQ, Vídeos\\Captures, Imágenes\\Screenshots, NVIDIA...), con una carpeta por juego o con el nombre del juego al principio del archivo."] = "Das Menü durchsucht die üblichen Ordner bereits selbst (Videos\\GameHQ, Videos\\Captures, Bilder\\Screenshots, NVIDIA ...), mit einem Ordner pro Spiel oder dem Spielnamen am Anfang des Dateinamens.";
            d["Pedir confirmación al finalizar, suspender, reiniciar o apagar"] = "Vor Beenden, Standby, Neustart oder Herunterfahren nachfragen";
            d["Silenciar el juego mientras está pausado"] = "Spiel stummschalten, solange es pausiert ist";
            d["Mostrar la batería del mando en el menú"] = "Controller-Akku im Menü anzeigen";
            d["Mostrar una miniatura del juego en el menú (en directo si el juego no se pausa; si está pausado, el último fotograma). Algunos juegos en pantalla completa exclusiva pueden verse en negro"] = "Eine Spielminiatur im Menü anzeigen (live, wenn das Spiel nicht pausiert ist; sonst das letzte Bild). Manche Spiele im exklusiven Vollbild erscheinen schwarz";
            d["No pausar juegos con anticheat (EasyAntiCheat, BattlEye, Vanguard, ACE...) ni los que tengan la etiqueta «No pausar» en Playnite: el menú se abre con el juego en marcha para no perder la partida online"] = "Spiele mit Anticheat (EasyAntiCheat, BattlEye, Vanguard, ACE ...) oder mit dem Playnite-Tag „Nicht pausieren“ nicht pausieren: Das Menü öffnet sich bei laufendem Spiel, damit die Online-Partie nicht verloren geht";
            d["Quitar automáticamente «Ejecutar como administrador» (marca de compatibilidad del usuario) de los juegos antes de iniciarlos, para poder pausarlos sin reiniciar"] = "„Als Administrator ausführen“ (Kompatibilitätsmarkierung des Benutzers) vor dem Start automatisch von Spielen entfernen, damit sie ohne Neustart pausiert werden können";
            d["Juegos que se ejecutan como administrador (Windows no deja a un Playnite normal pausarlos ni cerrarlos):"] = "Spiele, die als Administrator laufen (Windows erlaubt einem normalen Playnite weder Pausieren noch Beenden):";
            d["Abrir el menú encima, sin pausar el juego"] = "Menü darüber öffnen, ohne das Spiel zu pausieren";
            d["Solo avisar en pantalla (no abrir el menú)"] = "Nur auf dem Bildschirm warnen (Menü nicht öffnen)";
            d["Con la primera opción el juego sigue en marcha y puede recibir también los botones que pulses en el menú. La solución completa es ejecutar Playnite como administrador (así puede pausar y cerrar cualquier juego), o quitar «Ejecutar como administrador» en las propiedades del juego (el menú lo ofrece si lo detecta)."] = "Bei der ersten Option läuft das Spiel weiter und kann auch die Tasten empfangen, die du im Menü drückst. Die vollständige Lösung: Playnite als Administrator ausführen (dann kann es jedes Spiel pausieren und beenden) oder „Als Administrator ausführen“ in den Spieleigenschaften entfernen (das Menü bietet das an, wenn es dies erkennt).";
            d["Abrir también el menú de energía con el botón PS / atajo cuando no hay ningún juego en marcha (por defecto, el plugin solo actúa dentro de un juego)"] = "Das Energiemenü auch mit PS-Taste / Kürzel öffnen, wenn kein Spiel läuft (standardmäßig wirkt das Plugin nur im Spiel)";
            d["Mantener el juego delante: si Playnite aparece solo durante el juego (p. ej. al cerrar el overlay de capturas), se minimiza y se devuelve el juego al frente"] = "Spiel im Vordergrund halten: Erscheint Playnite während des Spiels von selbst (z. B. beim Schließen des Aufnahme-Overlays), wird es minimiert und das Spiel wieder nach vorn geholt";
            d["Comandos de energía (avanzado)"] = "Energiebefehle (erweitert)";
            d["Reiniciar:"] = "Neu starten:";
            d["Apagar:"] = "Herunterfahren:";
            d["Se ejecutan con cmd. Puedes sustituir el de apagar por un script propio, por ejemplo el que reproduce el vídeo de apagado."] = "Sie werden über cmd ausgeführt. Den Befehl zum Herunterfahren kannst du durch ein eigenes Skript ersetzen, z. B. eines, das das Herunterfahr-Video abspielt.";
            d["Idioma"] = "Sprache";
