            d["Automático (idioma de Playnite)"] = "Automatisch (Playnite-Sprache)";
            d["Para corregir o añadir un idioma, crea un archivo lang\\xx.txt en la carpeta de datos del plugin (una línea por frase: original, tabulador, traducción)."] = "Um eine Sprache zu korrigieren oder hinzuzufügen, erstelle im Datenordner des Plugins die Datei lang\\xx.txt (eine Zeile pro Satz: Original, Tabulator, Übersetzung).";
            d["Tema de Playnite: el fondo toma los colores del tema (si no los encuentra, usa los de la carátula). Color del juego: los de la carátula. Neutro: sin color."] = "Playnite-Theme: Der Hintergrund übernimmt die Farben des Themes (falls nicht gefunden, die des Covers). Spielfarbe: die des Covers. Neutral: ohne Farbe.";
            d["Confirmar acciones importantes"] = "Wichtige Aktionen bestätigen";
