            d["Silenciar el juego en pausa"] = "Spiel bei Pause stummschalten";
            d["Batería del mando"] = "Controller-Akku";
            d["Miniatura del juego"] = "Spiel-Vorschaubild";
            d["En directo si el juego no se pausa; si está pausado, el último fotograma. Algunos juegos en pantalla completa exclusiva pueden verse en negro."] = "Live, wenn das Spiel nicht pausiert wird; sonst das letzte Bild. Manche Spiele im exklusiven Vollbild können schwarz erscheinen.";
            d["Abrir el menú"] = "Menü öffnen";
            d["Botón Guía del mando (PS / Xbox)"] = "Guide-Taste des Controllers (PS / Xbox)";
            d["Pulsación corta: abrir el menú o volver al juego. Pulsación larga: menú de energía. Si otro programa (Steam, GameHQ...) usa ese botón, desactiva allí su acción."] = "Kurz drücken: Menü öffnen oder zum Spiel zurückkehren. Lang drücken: Energiemenü. Wenn ein anderes Programm (Steam, GameHQ...) diese Taste nutzt, deaktiviere dort die Aktion.";
            d["Select + Start (mantener 1 s)"] = "Select + Start (1 s halten)";
            d["Alternativa para mandos sin botón Guía o si otro programa lo ocupa."] = "Alternative für Controller ohne Guide-Taste oder wenn ein anderes Programm sie belegt.";
            d["Atajos de teclado"] = "Tastenkürzel";
            d["Modificadores:"] = "Modifikatoren:";
            d["Modificadores de los dos atajos. Asigna después estas combinaciones a un botón del mando con JoyToKey."] = "Modifikatoren für beide Tastenkürzel. Weise diese Kombinationen anschließend mit JoyToKey einer Controller-Taste zu.";
            d["Pulsación corta: abrir el menú del juego, o volver al juego. Pulsación larga: menú de energía."] = "Kurz drücken: Spielmenü öffnen oder zum Spiel zurückkehren. Lang drücken: Energiemenü.";
            d["Rellena los atajos habituales del programa; corrígelos si los has cambiado en él. Los que dejes vacíos no aparecen en el menú. Formato: Ctrl+Shift+S, Alt+F1, Win+Alt+PrtScn..."] = "Füllt die üblichen Tastenkürzel des Programms aus; passe sie an, falls du sie dort geändert hast. Leere erscheinen nicht im Menü. Format: Ctrl+Shift+S, Alt+F1, Win+Alt+PrtScn...";
            d["Carpetas extra:"] = "Zusätzliche Ordner:";
            d["Opcional, separadas por punto y coma. El menú ya busca en las carpetas habituales (GameHQ, Captures, Screenshots, NVIDIA...)."] = "Optional, durch Semikolons getrennt. Das Menü durchsucht bereits die üblichen Ordner (GameHQ, Captures, Screenshots, NVIDIA...).";
            d["Juegos"] = "Spiele";
            d["No pausar juegos con anticheat"] = "Spiele mit Anti-Cheat nicht pausieren";
            d["EasyAntiCheat, BattlEye, Vanguard, ACE... y los marcados con la etiqueta «No pausar»: el menú se abre con el juego en marcha para no perder la partida online."] = "EasyAntiCheat, BattlEye, Vanguard, ACE... und Spiele mit dem Tag „No pausar“: Das Menü öffnet sich bei laufendem Spiel, damit die Online-Partie nicht verloren geht.";
            d["Quitar «Ejecutar como administrador» al iniciar"] = "„Als Administrator ausführen“ beim Start entfernen";
            d["Quita esa marca de compatibilidad de los juegos antes de iniciarlos, para poder pausarlos sin reiniciar."] = "Entfernt diese Kompatibilitätseinstellung vor dem Start, damit sich Spiele ohne Neustart pausieren lassen.";
            d["Menú de energía fuera de un juego"] = "Energiemenü außerhalb eines Spiels";
            d["Abre también el menú de energía con el botón o el atajo cuando no hay ningún juego en marcha."] = "Öffnet das Energiemenü mit der Taste oder dem Tastenkürzel auch, wenn kein Spiel läuft.";
