            d["El menú ya busca solo en las carpetas habituales (Vídeos\\GameHQ, Vídeos\\Captures, Imágenes\\Screenshots, NVIDIA...), con una carpeta por juego o con el nombre del juego al principio del archivo."] = "메뉴는 일반적인 폴더(Videos\\GameHQ, Videos\\Captures, Pictures\\Screenshots, NVIDIA…)를 스스로 검색하며, 게임별 폴더 하나 또는 파일 이름 앞부분에 게임 이름이 있으면 됩니다.";
            d["Pedir confirmación al finalizar, suspender, reiniciar o apagar"] = "종료, 절전, 다시 시작, 종료할 때 확인 요청";
            d["Silenciar el juego mientras está pausado"] = "일시정지된 동안 게임 음소거";
